function joinLines(text, sep, opts){
  opts=opts||{};
  var lines=text.split(/\r\n|\r|\n/);
  if(opts.trim) lines=lines.map(function(l){return l.trim();});
  if(opts.skipEmpty) lines=lines.filter(function(l){return l.length>0;});
  var out=lines.map(function(l,i){ return opts.number?((i+1)+'. '+l):l; });
  return out.join(sep);
}
var EXPORTS={joinLines:joinLines};


if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.JoinForgePure = EXPORTS; }
